#include <vector>
#include <map>

class Solution {
public:
    std::vector<int> smallestPair(std::vector<int>& nums) {
        std::map<int, int> freq;
        for (int x : nums) freq[x]++;
        std::vector<int> uniques;
        for (const auto& [k, v] : freq) uniques.push_back(k);
        for (int i = 0; i < (int)uniques.size(); ++i) {
            for (int j = i + 1; j < (int)uniques.size(); ++j) {
                if (freq[uniques[i]] != freq[uniques[j]]) {
                    return {uniques[i], uniques[j]};
                }
            }
        }
        return {-1, -1};
    }
};

import java.util.*;

class Solution {
    public int[] smallestPair(int[] nums) {
        Map<Integer, Integer> freq = new TreeMap<>();
        for (int x : nums) freq.put(x, freq.getOrDefault(x, 0) + 1);
        List<Integer> uniques = new ArrayList<>(freq.keySet());
        for (int i = 0; i < uniques.size(); i++) {
            for (int j = i + 1; j < uniques.size(); j++) {
                if (!freq.get(uniques.get(i)).equals(freq.get(uniques.get(j)))) {
                    return new int[]{uniques.get(i), uniques.get(j)};
                }
            }
        }
        return new int[]{-1, -1};
    }
}

